<?php require_once __DIR__.'/lib/inicio.php';exigir_sesion();$c=obtener_caso((int)$_GET['id']);if($_SERVER['REQUEST_METHOD']==='POST'){try{validar_token();$f=$_FILES['archivo']??null;if(!$f||!is_uploaded_file($f['tmp_name']))throw new RuntimeException('Seleccione un archivo.');$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if(!in_array($ext,EXTENSIONES,true)||$f['size']>TAMANO_MAXIMO)throw new RuntimeException('Archivo no permitido o mayor a 15 MB.');$bin=file_get_contents($f['tmp_name']);$hash=hash('sha256',$bin);$uid=(int)usuario()['id_usuario'];$nulo=null;$s=bd()->prepare('INSERT INTO archivos_caso(id_caso,categoria,nombre_original,tipo_mime,tamano_bytes,hash_archivo,contenido,id_usuario_carga) VALUES(?,?,?,?,?,?,?,?)');$s->bind_param('isssissi',$c['id_caso'],$_POST['categoria'],$f['name'],$f['type'],$f['size'],$hash,$nulo,$uid);$s->send_long_data(6,$bin);$s->execute();bitacora('CARGA_ARCHIVO',$c['id_caso'],$f['name']);mensaje('Archivo guardado en sccmgpc.');ir('archivos.php?id='.$c['id_caso']);}catch(Throwable $e){mensaje($e->getMessage(),'error');ir('archivos.php?id='.$c['id_caso']);}}$s=bd()->prepare('SELECT id_archivo,categoria,nombre_original,tamano_bytes,fecha_carga FROM archivos_caso WHERE id_caso=? ORDER BY id_archivo DESC');$s->bind_param('i',$c['id_caso']);$s->execute();$archivos=$s->get_result()->fetch_all(MYSQLI_ASSOC);include 'encabezado.php';?><section class="tarjeta"><h1>Archivos del expediente</h1><form method="post" enctype="multipart/form-data"><input type="hidden" name="token" value="<?=token()?>"><label>Categoría</label><select name="categoria"><option>Solicitud</option><option>Recorrido de campo</option><option>Encuesta</option><option>Propuesta</option><option>Coordinación</option><option>Notificación</option><option>Complementario</option></select><label>Archivo</label><input type="file" name="archivo" required><button class="boton">Guardar archivo</button></form></section><section class="tarjeta"><table><tr><th>Categoría</th><th>Archivo</th><th>Tamaño</th><th>Fecha</th><th></th></tr><?php foreach($archivos as $a):?><tr><td><?=h($a['categoria'])?></td><td><?=h($a['nombre_original'])?></td><td><?=number_format($a['tamano_bytes']/1024,1)?> KB</td><td><?=h($a['fecha_carga'])?></td><td><a href="descargar_archivo.php?id=<?=$a['id_archivo']?>&caso=<?=$c['id_caso']?>">Descargar</a></td></tr><?php endforeach?></table></section><?php include 'pie.php';?>